package com.primehr.evidence.api;import com.primehr.evidence.application.EvidenceFrameworkService;import com.primehr.evidence.api.EvidenceFrameworkDtos.*;import com.primehr.security.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;import java.util.List;
@RestController @RequestMapping("/api/primehr/v1/evidence/frameworks") public class EvidenceFrameworkController{private final EvidenceFrameworkService service;private final EvidenceFrameworkPermissionGuard permission;private final AgencyScopeResolver agency;public EvidenceFrameworkController(EvidenceFrameworkService service,EvidenceFrameworkPermissionGuard permission,AgencyScopeResolver agency){this.service=service;this.permission=permission;this.agency=agency;}@GetMapping public List<FrameworkResponse>list(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t){permission.require(PrimeHrAction.ACCESS,t);return service.list(agency.resolveAgencyId(a));}@GetMapping("/effective")public FrameworkResponse effective(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestParam LocalDate on){permission.require(PrimeHrAction.ACCESS,t);return service.effective(agency.resolveAgencyId(a),on);}@GetMapping("/{id}")public FrameworkResponse get(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){permission.require(PrimeHrAction.ACCESS,t);return service.get(agency.resolveAgencyId(a),id);}@PostMapping@ResponseStatus(HttpStatus.CREATED)public FrameworkResponse create(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@Valid@RequestBody FrameworkInput i){permission.require(PrimeHrAction.ADD,t);return service.create(agency.resolveAgencyId(a),i,c);}@PutMapping("/{id}")public FrameworkResponse update(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody FrameworkInput i){permission.require(PrimeHrAction.EDIT,t);return service.update(agency.resolveAgencyId(a),id,i,c);}@PutMapping("/{id}/content")public FrameworkResponse content(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody ContentInput i){permission.require(PrimeHrAction.EDIT,t);return service.replaceContent(agency.resolveAgencyId(a),id,i,c);}@PostMapping("/{id}/revisions")@ResponseStatus(HttpStatus.CREATED)public FrameworkResponse revise(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody Transition i){permission.require(PrimeHrAction.ADD,t);return service.revise(agency.resolveAgencyId(a),id,i,c);}@PostMapping("/{id}/publish")public FrameworkResponse publish(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody Publish i){permission.require(PrimeHrAction.PUBLISH,t);return service.publish(agency.resolveAgencyId(a),id,i,c);}@PostMapping("/{id}/retire")public FrameworkResponse retire(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody Transition i){permission.require(PrimeHrAction.ARCHIVE,t);return service.retire(agency.resolveAgencyId(a),id,i,c);}}
